// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger) public {
        // Assume _logger is not the contract owner (address(0) default owner)
        vm.assume(_logger != address(0));
        // The reference C should return false for any address not approved
        bool result = c.approvedToLog(_logger);
        // No logger has been approved yet, so approvedToLog must return false
        assertTrue(result == false);
    }
}

